WITH products_by_supplier AS (SELECT supplier_id, ROUND((100 * SUM(CASE WHEN category = 'Books' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_books FROM products GROUP BY supplier_id) SELECT s.id, s.rating, s.country, pbs.pct_books FROM suppliers s INNER JOIN products_by_supplier pbs ON s.id = pbs.supplier_id
